import math

def check(sample):
    lines = sample.get("lines")
    line = lines.get("yellow")
    if line == None:
        return {"value": False, "measure": None, "why": "no yellow line"}
    p1 = line[0]
    p2 = line[1]
    x1 = p1[0]
    y1 = p1[1]
    x2 = p2[0]
    y2 = p2[1]
    if x1 == x2:
        return {"value": False, "measure": None, "why": "vertical yellow line"}
    objects = sample.get("objects")
    count = 0
    for obj in objects:
        concept = obj.get("concept")
        if concept.lower() != "pallet":
            continue
        box = obj.get("box_xyxy_px")
        top = obj.get("mask_top_y_px")
        cx = (box[0] + box[2]) / 2
        line_y = y1 + (y2 - y1) * (cx - x1) / (x2 - x1)
        if top < line_y:
            count = count + 1
    if count > 0:
        return {"value": True, "measure": float(count), "why": "pallet above yellow line"}
    return {"value": False, "measure": None, "why": "no pallet above yellow line"}

